const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const { createServer, CONFIG_PATH } = require('../server.js');

// AC-001: WHEN config/hello.json 就位为 {"message":"hello"} 且收到 GET /api/hello 请求
// THE SYSTEM SHALL 返回 200 且响应体恰为该文件的完整 JSON 内容。
test('GET /api/hello 返回 200 且响应体恰为 config/hello.json 的完整 JSON 内容', async (t) => {
  // 前置：config/hello.json 必须已就位（由需求方线下提供），否则本测试失败
  const expected = fs.readFileSync(CONFIG_PATH, 'utf8');

  const server = createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  t.after(() => new Promise((resolve) => server.close(resolve)));

  const { port } = server.address();
  const response = await fetch(`http://127.0.0.1:${port}/api/hello`);

  assert.equal(response.status, 200);
  assert.equal(await response.text(), expected);
});
