'use strict';

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

// 仓库根目录下的 config/hello.json（TASK-001 契约数据源）
const CONFIG_PATH = path.join(__dirname, 'config', 'hello.json');

function createServer() {
  return http.createServer((req, res) => {
    const { pathname } = new URL(req.url, 'http://localhost');

    if (req.method !== 'GET' || pathname !== '/api/hello') {
      res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify({ error: 'Not Found' }));
      return;
    }

    // 读取 config/hello.json 并以 200 返回其完整 JSON 内容
    fs.readFile(CONFIG_PATH, 'utf8', (err, data) => {
      if (err) {
        res.writeHead(500, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(JSON.stringify({ error: 'config/hello.json 不可读' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(data);
    });
  });
}

module.exports = { createServer, CONFIG_PATH };

if (require.main === module) {
  const port = Number(process.env.PORT) || 3000;
  createServer().listen(port, () => {
    console.log(`server listening on http://127.0.0.1:${port}`);
  });
}

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const { createServer, CONFIG_PATH } = require('../server.js');

// AC-001: WHEN config/hello.json 就位为 {"message":"hello"} 且收到 GET /api/hello 请求
// THE SYSTEM SHALL 返回 200 且响应体恰为该文件的完整 JSON 内容。
test('GET /api/hello 返回 200 且响应体恰为 config/hello.json 的完整 JSON 内容', async (t) => {
  // 前置：config/hello.json 必须已就位（由需求方线下提供），否则本测试失败
  const expected = fs.readFileSync(CONFIG_PATH, 'utf8');

  const server = createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  t.after(() => new Promise((resolve) => server.close(resolve)));

  const { port } = server.address();
  const response = await fetch(`http://127.0.0.1:${port}/api/hello`);

  assert.equal(response.status, 200);
  assert.equal(await response.text(), expected);
});

